代码模板:
void backtrack(int n, int open, int close, string& path, vector<string>& ans) {
    if (open == n && close == n) {
        ans.push_back(path);
        return;
    }
    if (open < n) {
        path.push_back('(');
        backtrack(n, open + 1, close, path, ans);
        path.pop_back(); // 撤销
    }
    if (close < open) {
        path.push_back(')');
        backtrack(n, open, close + 1, path, ans);
        path.pop_back(); // 撤销
    }
}
// 两个if条件不是互斥的 | open<n时还可加'(' | close<open时还可加')'
